use_bpm 170

# melody octave shift per bar range; other bars play as written
SHIFTS = {
  (145..168) => -24,		# recap: low sax, piano follows down
}

define :shift_at do |t|
  bar = (t / 3).floor + 1
  hit = SHIFTS.find { |range, _| range.include?(bar) }
  hit ? hit[1] : 0
end

define :moved do |ns, semis|
  if ns == :r then :r
  elsif ns.is_a?(Array) then ns.map { |x| x + semis }
  else ns + semis
  end
end

define :perform do |part, vol, follow|
  use_synth :piano
  t = 0
  part.each do |ns, b, len|
    ns = moved(ns, shift_at(t)) if follow
    play ns, sustain: len * 0.9, release: 0.3, amp: vol
    sleep b
    t += b
  end
end

# sax-ish lead: blade with delayed vibrato, darker and louder when low
define :sax do |part|
  use_synth :blade
  t = 0
  part.each do |ns, b, len|
    semis = shift_at(t)
    low = semis < 0
    play moved(ns, semis), attack: 0.08, sustain: len * 0.8,
    release: 0.25, cutoff: low ? 78 : 95, amp: low ? 1.2 : 0.8,
    vibrato_rate: 5.5, vibrato_depth: 0.12,
    vibrato_delay: 0.25, vibrato_onset: 0.2
    sleep b
    t += b
  end
end

with_fx :reverb, room: 0.5, mix: 0.3 do
  in_thread do
    sax MELODY
  end
  in_thread do
    perform MELODY_HI, 0.6, true
  end
  perform ACCOMP, 0.7, false
end
